<?php $this->layout('default'); use Moves\Services\CmsShowcase as S; use Moves\Support\CmsView as V; $rows = S::testimonials(); $edit = null; foreach ($rows as $r) { if ((string) $r['id'] === V::queryString('editar')) { $edit = $r; } } $pub = count(array_filter($rows, static fn ($r) => $r['status'] === 'published')); $rating = (int) ($edit['rating'] ?? 5); ?>
<?= V::kpis([['quote', 'Depoimentos', (string) count($rows), 'cadastrados'], ['check', 'Visíveis', (string) $pub, 'no site'], ['pages', 'Rascunhos', (string) (count($rows) - $pub), 'aguardando publicação'], ['chart', 'Nota média', $rows === [] ? '—' : number_format(array_sum(array_column($rows, 'rating')) / count($rows), 1, ',', ''), 'de 5 estrelas']]) ?>
<div class="cms-form-list"><form class="cms-card" method="post" action="/acao/testimonial-save" enctype="multipart/form-data"><header class="cms-card-head"><div><h2><?= $edit ? 'Editar depoimento' : 'Cadastrar depoimento' ?></h2><small>A foto pode ser enviada ou escolhida na biblioteca.</small></div><?= V::icon('quote') ?></header><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?: '' ?>"><div class="cms-form-grid"><?= V::field('Nome da pessoa *', 'person_name', $edit['person_name'] ?? '', ['required' => true]) ?><?= V::field('Empresa', 'company', $edit['company'] ?? '') ?></div><?= V::field('Depoimento *', 'body', $edit['body'] ?? '', ['type' => 'textarea', 'rows' => 5, 'required' => true]) ?>
<fieldset class="cms-field" style="border:0;padding:0"><legend style="font-weight:600;font-size:.84rem;margin-bottom:5px">Avaliação</legend><div class="cms-stars"><?php for ($i = 5; $i >= 1; $i--): ?><input type="radio" id="star-<?= $i ?>" name="rating" value="<?= $i ?>"<?= $i === $rating ? ' checked' : '' ?>><label for="star-<?= $i ?>" title="<?= $i ?> estrela(s)" aria-label="<?= $i ?> estrela(s)">★</label><?php endfor; ?></div></fieldset>
<div class="cms-form-grid"><?= V::field('Status', 'status', $edit['status'] ?? 'draft', ['type' => 'select', 'choices' => ['draft' => 'Rascunho', 'published' => 'Publicado']]) ?><?= V::field('Enviar nova foto', 'photo_file', '', ['type' => 'file']) ?></div><?= V::mediaField('Foto da biblioteca', 'photo_path', $edit['photo_path'] ?? null) ?><div class="cms-form-end"><button class="cms-btn-primary">Salvar depoimento</button></div></form>
<section class="cms-card"><header class="cms-card-head"><div><h2>Depoimentos cadastrados</h2><small>Somente os publicados aparecem no site.</small></div><b class="cms-count"><?= count($rows) ?></b></header><?php if ($rows === []): ?><?= V::empty('Nenhum depoimento cadastrado.') ?><?php endif; foreach ($rows as $t): ?><article class="cms-quote"><?= $t['photo_path'] ? '<img class="cms-photo" src="' . V::e($t['photo_path']) . '" alt="">' : '<i class="cms-photo">' . V::e(mb_strtoupper(mb_substr($t['person_name'], 0, 1))) . '</i>' ?><div><div class="cms-quote-top"><strong><?= V::e($t['person_name']) ?></strong><span class="cms-td-actions"><?= V::badge($t['status'], $t['status'] === 'published' ? 'Publicado' : 'Rascunho') ?><?= V::iconLink('?editar=' . (int) $t['id'], 'Editar') ?><?= V::iconAction('testimonial-delete', 'Excluir', ['id' => $t['id']], 'Excluir este depoimento?') ?></span></div><span class="cms-star-view" role="img" aria-label="<?= (int) $t['rating'] ?> de 5 estrelas"><?= str_repeat('★', (int) $t['rating']) ?></span><?php if ($t['company'] !== ''): ?><br><small><?= V::e($t['company']) ?></small><?php endif; ?><p><?= V::e($t['body']) ?></p></div></article><?php endforeach; ?></section></div>
